    """
    Sorts a rectangular matrix in ascending order based on the sum of its rows.

    Args:
        matrix (list of lists): A rectangular matrix containing integers.

    Returns:
        list of lists: A new matrix sorted by row sums.

    Raises:
        TypeError: If the input is not a list of lists or if any element is not an integer.
        ValueError: If the matrix is not rectangular.
    """
    # Check if the input is a list
    if not isinstance(matrix, list):
        raise TypeError("The input must be a list of lists.")

    if not matrix:
        return []

    # Check if every element in the matrix is a list and contains only integers
