        if not isinstance(row, list):
            raise TypeError("The input must be a list of lists.")
        for element in row:
            if not isinstance(element, int):
                raise TypeError("All elements in the matrix must be integers.")

    # Validate that the matrix is rectangular
    row_length = len(matrix[0])
    if not all(len(row) == row_length for row in matrix):
        raise ValueError("The input must be a rectangular matrix (all rows must have the same length).")

    # Return a new list sorted by the sum of each sublist
    return sorted(matrix, key=sum)

