from collections import Counter

def count_common(data, n=5):
    """
    Counts the most common words across all values in a dictionary.

    :param data: Dictionary where values are strings or lists of strings.
    :param n: Number of most common words to return.
    :return: A list of tuples (word, count).
    """
    all_words = []
    for value in data.values():
        if isinstance(value, str):
            all_words.extend(value.lower().split())
        elif isinstance(value, list):
            all_words.extend([str(word).lower() for word in value])

    return Counter(all_words).most_common(n)

